/// Простой разбор SVG-пути: абсолютные команды M, C, L, Z.
Path parseSvgPath(String data) {
  final tokens = RegExp(r'[MCLZ]|-?\d*\.?\d+(?:e-?\d+)?').allMatches(data).map((m) => m.group(0)!).toList();
  final path = Path();
  var i = 0;
  String cmd = 'M';
  double n() => double.parse(tokens[i++]);
  while (i < tokens.length) {
    final t = tokens[i];
    if (t == 'M' || t == 'C' || t == 'L' || t == 'Z') {
      cmd = t;
      i++;
      if (cmd == 'Z') {
        path.close();
        continue;
      }
    }
    switch (cmd) {
      case 'M':
        path.moveTo(n(), n());
        cmd = 'L'; // последующие пары после M — это L
      case 'L':
        path.lineTo(n(), n());
      case 'C':
        path.cubicTo(n(), n(), n(), n(), n(), n());
      default:
        i++;
    }
  }
  return path;
}

final Path _leafPath = parseSvgPath(kLeafPathData);

/// Рисует лист в квадрате [size]×[size].
class LeafPainter extends CustomPainter {
  LeafPainter(this.color);

  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final s = size.shortestSide / 92;
    canvas.translate((size.width - 92 * s) / 2, (size.height - 92 * s) / 2);
    canvas.scale(s);
    canvas.translate(-4, -4);
    canvas.drawPath(_leafPath, Paint()..color = color..isAntiAlias = true);
  }

  @override
  bool shouldRepaint(LeafPainter old) => old.color != color;
}

class LeafMark extends StatelessWidget {
  const LeafMark({super.key, required this.size, required this.color});

  final double size;
  final Color color;

  @override
  Widget build(BuildContext context) =>
      SizedBox.square(dimension: size, child: CustomPaint(painter: LeafPainter(color)));
}
